with.script:
const { owner, repo } = context.repo;
const branch = context.payload.pull_request.head.ref;

const workflows = await github.rest.actions.listWorkflowRunsForRepo({
  owner,
  repo,
  branch,
  status: 'in_progress',
});

const waitingWorkflows = await github.rest.actions.listWorkflowRunsForRepo({
  owner,
  repo,
  branch,
  status: 'queued',
});

const runs = [...workflows.data.workflow_runs, ...waitingWorkflows.data.workflow_runs];

for (const run of runs) {
  if (run.id === context.runId) {
    continue;
  }
  try {
    console.log(`Cancelling run ${run.id} (${run.name})`);
    await github.rest.actions.cancelWorkflowRun({
      owner,
      repo,
      run_id: run.id,
    });
  } catch (error) {
    console.log(`Failed to cancel run ${run.id}: ${error.message}`);
  }
}

console.log(`Cancelled ${runs.length > 1 ? runs.length - 1 : 0} workflow run(s) for branch ${branch}`);

const highRiskFiles = process.env.high_risk_code;
const fileList = highRiskFiles.split(',').map(file => `- [ ] ${file}`).join('\n');
github.rest.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: `### 🚨 Detected changes in high risk code 🚨 \n High-risk code has higher potential to break the SDK and may be hard to test. To prevent severe bugs, apply the rollout process for releasing such changes and be extra careful when changing and reviewing these files:\n ${fileList}`
})

steps.run:
set -e
CORE_TARBALL=$(find "$GITHUB_WORKSPACE/packages/core" -name 'sentry-react-native-*.tgz' -print -quit)
EXPO_TARBALL=$(find "$GITHUB_WORKSPACE/packages/expo-upload-sourcemaps" -name 'sentry-expo-upload-sourcemaps-*.tgz' -print -quit)
[ -n "$CORE_TARBALL" ] || { echo "::error::core tarball not found"; exit 1; }
[ -n "$EXPO_TARBALL" ] || { echo "::error::expo-upload-sourcemaps tarball not found"; exit 1; }
npm install "$EXPO_TARBALL" "$CORE_TARBALL"
